import bpy
M = bpy.data.materials
coll = bpy.data.collections["베이스기타"]
mats = {o.name.replace("베이스기타_", ""): o.data.materials[0] for o in coll.objects}
mats.pop("로고", None); mats["로고_바디"] = M["글자"]; mats["로고_넥"] = M["글자"]
for o in list(coll.objects): bpy.data.objects.remove(o, do_unlink=True)
def imp(path, name, m, c, loc=(0,0,0)):
    bpy.ops.wm.stl_import(filepath=path)
    n = bpy.context.object
    for cc in n.users_collection: cc.objects.unlink(n)
    c.objects.link(n); n.name = name; n.data.materials.append(m); n.location = loc
    bpy.context.view_layer.objects.active = n; n.select_set(True)
    bpy.ops.object.shade_auto_smooth(angle=0.6)
    return n
for name, m in mats.items():
    imp(f"/Users/jjunu/99_project_AX_1111/build/parts/{name}.stl", "베이스기타_" + name, m, coll)
pc = bpy.data.collections.get("꽂은빼빼로") or bpy.data.collections.new("꽂은빼빼로")
if pc.name not in bpy.context.scene.collection.children: bpy.context.scene.collection.children.link(pc)
for o in list(pc.objects): bpy.data.objects.remove(o, do_unlink=True)
holes = {"오리지널": (-22.0, 19.0), "아몬드": (22.0, 19.0), "화이트줄무늬": (-27.0, 3.0)}
coat_mat = {"오리지널": M["초코"], "아몬드": M["초코"], "화이트줄무늬": M["초코"]}
for k, (x, y) in holes.items():
    loc = (x, y, 12.0 - 9.0)
    imp(f"/Users/jjunu/99_project_AX_1111/stl/{k}_세움_과자.stl", k + "_과자", M["과자"], pc, loc)
    o = imp(f"/Users/jjunu/99_project_AX_1111/stl/{k}_세움_초코.stl", k + "_초코", M["초코"], pc, loc)
    # 토핑 색: 코팅 바깥(반지름 4 초과)으로 튀어나온 면
    extra = M["아몬드"] if k == "아몬드" else M["화이트초코"] if k == "화이트줄무늬" else None
    if extra:
        o.data.materials.append(extra)
        for p in o.data.polygons:
            if (p.center.x**2 + p.center.y**2) ** 0.5 > 4.05: p.material_index = 1
bpy.ops.wm.save_mainfile()
print("ok")

